#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void scan_kernel(const half* input, half* output, int total_elements, int dim_size, int stride) {
    // Shared memory for block-level scan
    extern __shared__ half shared_data[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Process each element in the batch
    for (int i = 0; i < total_elements; i += dim_size * stride) {
        // Load data into shared memory
        if (tid < dim_size) {
            int idx = i + tid * stride;
            if (idx < total_elements) {
                shared_data[tid] = input[idx];
            } else {
                shared_data[tid] = __float2half(0.0f);
            }
        }
        __syncthreads();

        // Up-sweep (reduce) phase
        for (int stride = 1; stride < dim_size; stride *= 2) {
            int index = (tid + 1) * stride * 2 - 1;
            if (index < dim_size) {
                shared_data[index] += shared_data[index - stride];
            }
            __syncthreads();
        }

        // Down-sweep phase
        if (tid == 0 && dim_size > 0) {
            shared_data[dim_size - 1] = __float2half(0.0f);
        }
        __syncthreads();

        for (int stride = dim_size / 2; stride > 0; stride /= 2) {
            int index = (tid + 1) * stride * 2 - 1;
            if (index < dim_size) {
                half temp = shared_data[index];
                shared_data[index] += shared_data[index - stride];
                shared_data[index - stride] = temp;
            }
            __syncthreads();
        }

        // Write back results
        if (tid < dim_size) {
            int idx = i + tid * stride;
            if (idx < total_elements) {
                output[idx] = shared_data[tid];
            }
        }
        __syncthreads();
    }
}

// Optimized version for contiguous memory access
__global__ void scan_kernel_optimized(const half* input, half* output, int total_elements, int dim_size, int stride) {
    extern __shared__ half shared_data[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Each block handles one batch
    int batch_offset = batch_idx * dim_size * stride;

    // Load data into shared memory
    for (int i = 0; i < dim_size; i += blockDim.x) {
        int idx = i + tid;
        if (idx < dim_size) {
            shared_data[idx] = input[batch_offset + idx * stride];
        } else {
            shared_data[idx] = __float2half(0.0f);
        }
    }
    __syncthreads();

    // Perform inclusive scan
    for (int stride = 1; stride < dim_size; stride *= 2) {
        if (tid >= stride && tid < dim_size) {
            shared_data[tid] += shared_data[tid - stride];
        }
        __syncthreads();
    }

    // Write back results
    for (int i = 0; i < dim_size; i += blockDim.x) {
        int idx = i + tid;
        if (idx < dim_size) {
            output[batch_offset + idx * stride] = shared_data[idx];
        }
    }
}

void launch_scan_kernel(const half* input, half* output, int total_elements, int dim_size, int num_batches) {
    const int block_size = 256;
    size_t shared_mem_size = dim_size * sizeof(half);

    // Adjust for compute capability 8.0
    dim3 grid(num_batches);
    dim3 block(block_size);

    // For small dimensions, use optimized version
    if (dim_size <= 1024) {
        scan_kernel_optimized<<<grid, block, shared_mem_size>>>(input, output, total_elements, dim_size, 1);
    } else {
        // For large dimensions, fall back to original approach
        int chunks = (dim_size + block_size - 1) / block_size;
        for (int chunk = 0; chunk < chunks; ++chunk) {
            int start = chunk * block_size;
            int end = min(start + block_size, dim_size);
            int local_dim_size = end - start;
            scan_kernel<<<grid, block, shared_mem_size>>>(input, output, total_elements, local_dim_size, 1);
        }
    }
}
